import {visionCases} from './content.js?v=castle-first-1';

// The curriculum follows five real case films. Every scene waits for the presenter.
export const visionCurriculum=[
 {id:'organize',title:'讓每份經驗，都有學習的起點。',subtitle:'專案管理 · 資料整理',note:'承接五個案例。像生命體開始整理記憶，不同場域的影像先分專案、分資料集，留下可以學習的樣本。左側沿用簡報案例圖，右側展示官方資料集列表。兩者的匯流為流程示意，不宣稱這些資料已載入該官方範例。'},
 {id:'label',title:'教會它，看見什麼、如何分辨。',subtitle:'AI 輔助標註 / 官方產品介面',note:'展示官方蝴蝶多邊形標註介面。從選擇目標、AI 輔助圈選，到檢查修正，讓人的判斷成為模型的學習依據。官網的效率數字不作為本次成效承諾。'},
 {id:'tasks',title:'一雙眼睛，學會不同的判斷。',subtitle:'分類 · 偵測 · 分割 · 異常偵測',note:'用四種不同任務說明：這是什麼、在哪裡、輪廓在哪、哪裡不尋常。四張圖沿用使用者提供的 Pitch 素材：Wafer Map 分類、瓶蓋瑕疵偵測、齒列分割與網布正常樣本。齒列為分割技術展示，網布畫面為正常樣本，不宣稱醫療診斷或新增客戶成效。'},
 {id:'train',title:'從看過的樣本，學會判斷新影像。',subtitle:'資料 → 模型訓練 → 驗證',note:'訓練動畫呈現已標註樣本進入模型，從樣本學習特徵，再用驗證資料檢視結果。光流與模型為示意，不顯示捏造的準確率或訓練時間。'},
 {id:'workspace',title:'每一次學習，都看得見進展。',subtitle:'訓練歷程 / 官方產品介面',note:'展示官方模型分析介面。比較訓練與驗證的變化，檢視模型是否學到可泛化的特徵；指標是檢查與修正的依據。曲線及數字皆為官方示範資料，不是本次案例實測或準確率承諾。'},
 {id:'validate',title:'學會了什麼，讓結果說話。',subtitle:'模型驗證 / 官方產品介面',note:'用官方驗證畫面檢查模型輸出，回看判錯或漏判的影像，修正資料與標註，再持續驗證。畫面內數字為官方示範資料。'},
 {id:'deploy',title:'真正的學習，回到現場才完整。',subtitle:'模型 → WinEdge-V → 現場回饋',note:'驗證後將模型部署至 WinEdge-V，搭載 Edge 硬體接收現場影像。新的情境回到下一次資料整理與訓練；沒有宣稱無人審核的自動重訓。下一步由所有專案積木一起融合，誕生 AIWinOps。'}
];

const line=(d,i=0)=>`<path class="av-wire" d="${d}"/><path class="av-flow" d="${d}" style="--i:${i}"/>`;
const frame=(body,label)=>`<svg viewBox="0 0 1000 500" class="av-routes" preserveAspectRatio="none" aria-label="${label}">${body}</svg>`;
const model=()=>`<div class="av-model"><svg viewBox="0 0 220 220" aria-hidden="true"><path d="M110 20L190 65V155L110 200 30 155V65Z"/><path d="M30 65L110 110 190 65M110 110V200M110 20V110M30 155L110 110 190 155"/>${[[110,20],[190,65],[190,155],[110,200],[30,155],[30,65],[110,110]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="5" style="--i:${i}"/>`).join('')}</svg></div>`;
function workspaceFrame(asset,title,caption){return `<figure class="av-screen" data-av-asset="${asset}"><div class="av-screen-bar"><b>AIWinOps <span>/ ${title}</span></b><span>PRODUCT WORKSPACE</span></div><div class="av-screen-image"><img src="./assets/aiwinops/${asset}.webp" alt="AIWinOps 官方${title}介面"/></div><figcaption>${caption}</figcaption></figure>`;}
function organized(){return `<div class="av-organize">${frame([60,155,250,345,440].map((y,i)=>line(`M235 ${y}C265 ${y} 265 250 300 250`,i)).join(''),'五個案例整理為可學習的影像資產')}<div class="av-archive">${visionCases.map((c,i)=>`<article style="--i:${i}"><img src="./assets/${c.image}" alt="${c.title}案例畫面"/><div><small>PROJECT 0${i+1}</small><h2>${c.title}</h2></div></article>`).join('')}</div><div class="av-dataset-workspace">${workspaceFrame('prepare','專案與資料集','每個現場的經驗，都成為可管理的影像資產。')}</div></div>`;}
function tasks(){return `<div class="av-tasks">${[
 ['classification','分類','辨識缺陷類型','Wafer Map','pitch-wafer-map.png'],
 ['detection','物件偵測','找出位置與瑕疵','瓶蓋檢測','vision/caps.jpg'],
 ['segmentation','影像分割','分辨每一個輪廓','齒列分割技術展示','pitch-tooth-segmentation.png'],
 ['anomaly','異常偵測','從正常樣本學習','網布正常樣本','pitch-mesh-anomaly.png']
].map(([id,title,q,caseTitle,img],i)=>`<article style="--i:${i}" data-av-task="${id}"><div class="av-task-image"><img src="./assets/${img}" alt="${caseTitle}：使用者提供的簡報畫面"/><i class="av-scan"></i></div><header><small>0${i+1} / ${id.toUpperCase()}</small><h2>${title}</h2><p>${q}</p><span>${caseTitle}</span></header></article>`).join('')}</div>`;}

function training(){return `<div class="av-training">${frame(line('M280 250H420')+line('M605 250H755',1),'標註資料經模型學習後，使用不同影像驗證')}<div class="av-training-input"><small>LABELED DATA</small><div class="av-samples">${visionCases.slice(0,4).map((c,i)=>`<img src="./assets/${c.image}" alt="" style="--i:${i}"/>`).join('')}</div><h2>給它學習的依據</h2><p>影像 × 標註</p></div><div class="av-training-core">${model()}<h2>訓練模型</h2><p>學習特徵與判斷方式</p><div class="av-epochs"><i></i><i></i><i></i></div></div><div class="av-validation"><small>VALIDATION</small><div class="av-check-frame"><img src="./assets/aiwinops/detection.webp" alt="官方物件偵測示意"/><i></i></div><h2>面對新的影像</h2><p>檢視結果 · 持續修正</p></div><div class="av-learning-loop"><span>每一次驗證，讓下一次學習更有方向。</span><i></i></div></div>`;}
const screenTitles={label:'AI 輔助標註',workspace:'模型分析',validate:'模型驗證'};
function screen(id){const spec={
 label:{asset:'annotate',caption:'AI 輔助圈選，讓人的判斷成為學習依據。',steps:[['選擇目標','物件、類別與區域'],['AI 輔助','加速建立標註'],['確認與修正','留下正確的學習依據']]},
 workspace:{asset:'training',caption:'官方模型分析示範畫面 · 數值為示範資料',steps:[['看見過程','觀察每一輪學習'],['比較結果','訓練與驗證一起看'],['持續改善','找到資料與模型的修正方向']]},
 validate:{asset:'validate',caption:'檢視輸出 → 找到問題 → 修正與再驗證',steps:[['驗證新影像','檢查模型的判讀'],['回看錯誤','找到漏判與誤判'],['累積經驗','回到下一次學習']]}
 }[id];return `<div class="av-product-demo">${workspaceFrame(spec.asset,screenTitles[id],spec.caption)}<aside class="av-demo-guide">${spec.steps.map(([title,text],i)=>`<div style="--i:${i}"><small>0${i+1}</small><h2>${title}</h2><p>${text}</p></div>`).join('')}<span>從操作，到可重複的能力。</span></aside></div>`;}

function edge(){return `<svg viewBox="0 0 500 260" class="av-edge" aria-label="Edge 工業主機示意"><defs><linearGradient id="av-metal" x2="0" y2="1"><stop stop-color="#7b8e9e"/><stop offset="1" stop-color="#2c3c4d"/></linearGradient></defs><path fill="#374e61" d="M35 90L115 25H455L390 90Z"/><path fill="url(#av-metal)" d="M35 90H390V218H35Z"/><path fill="#172735" d="M390 90L455 25V160L390 218Z"/>${Array.from({length:14},(_,i)=>`<path fill="#8195a5" d="M${48+i*24} 82L${122+i*22} 26V40L${48+i*24} 96Z"/>`).join('')}<rect x="49" y="110" width="325" height="90" rx="4" fill="#09121c"/>${[72,133].map(x=>`<rect x="${x}" y="140" width="45" height="34" fill="#91a5b1"/><rect x="${x+5}" y="145" width="35" height="24" fill="#142431"/>`).join('')}${[205,250].map(x=>`<rect x="${x}" y="148" width="28" height="17" fill="#0b101a" stroke="#8f9eaa" stroke-width="4"/>`).join('')}<circle cx="336" cy="143" r="4" fill="#94d4be"/><circle cx="336" cy="161" r="4" fill="#94d4be"/><path fill="#667b8c" d="M15 218H402L416 235H15Z"/></svg>`;}
function deployment(){return `<div class="av-deployment"><div class="av-deploy-model">${model()}<h2>經過驗證的模型</h2><p>把學到的能力，帶到現場。</p></div><div class="av-deploy-beam"><i></i></div><div class="av-deploy-edge">${edge()}<h2>WinEdge-V</h2><p>Edge 硬體 × 現場影像推論</p></div><div class="av-deploy-results"><article><small>INPUT</small><h3>相機與影像</h3><p>工業相機 · IP / USB · 串流</p></article><article><small>OUTPUT</small><h3>判讀與回饋</h3><p>檢測結果 · 事件 · 現場系統</p></article></div><div class="av-learning-loop"><span>現場的新經驗 → 整理與標註 → 下一次模型學習</span><i></i></div></div>`;}
const camera=()=>`<svg class="av-camera" viewBox="0 0 350 260" aria-label="工業取像設備示意"><defs><linearGradient id="av-camera-metal"><stop stop-color="#96a7b3"/><stop offset=".5" stop-color="#344758"/><stop offset="1" stop-color="#79909f"/></linearGradient><radialGradient id="av-lens"><stop stop-color="#1b4a62"/><stop offset=".45" stop-color="#0b2231"/><stop offset="1" stop-color="#030a11"/></radialGradient></defs><path fill="#576d7e" d="M76 72L137 35H287L235 73Z"/><path fill="#253b4a" d="M235 73L287 35V159L235 199Z"/><rect x="76" y="72" width="160" height="128" rx="8" fill="url(#av-camera-metal)"/><rect x="84" y="79" width="145" height="113" rx="5" fill="#101d29"/><path fill="#748996" d="M141 198H174V228H215V242H106V228H141Z"/><ellipse cx="144" cy="136" rx="61" ry="58" fill="#a2b3bc"/><ellipse cx="140" cy="136" rx="55" ry="53" fill="#152735"/>${[45,48,51].map(r=>`<ellipse cx="139" cy="136" rx="${r}" ry="${r*.96}" fill="none" stroke="#66808d" stroke-width=".8"/>`).join('')}<ellipse cx="138" cy="136" rx="40" ry="38" fill="url(#av-lens)" stroke="#9cbdc9"/><ellipse cx="130" cy="122" rx="13" ry="10" fill="#9cd5eb" opacity=".13"/><path d="M111 119a29 29 0 0 1 34-10" fill="none" stroke="#a7d7e4" opacity=".45" stroke-width="2"/>${[[91,89],[217,89],[91,181],[217,181]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3" fill="#8399a6"/>`).join('')}</svg>`;
export function visionHardwareHTML(index){const c=visionCases[index],h=c.hardware;return `<section class="av-keynote av-hardware"><header><div><p class="av-kicker">FROM THE FIELD / 0${index+1}</p><h1>${c.title}，接回真實現場。</h1></div><p>影像輸入 → 現場推論 → 結果回饋</p></header><div class="av-stage av-hardware-flow">${frame(line('M240 255H375')+line('M625 255H755',1),'影像在 Edge 硬體上推論，輸出回到現場')}<article><small>01 / INPUT</small>${camera()}<h2>${h.device}</h2><p>${h.input}</p></article><article><small>02 / EDGE INFERENCE</small>${edge()}<h2>WinEdge-V</h2><p>搭載 Edge 硬體，於現場推論。</p></article><article><small>03 / OUTPUT</small><div class="av-hardware-result"><img src="./assets/${c.image}" alt="${c.title}檢測畫面"/></div><h2>現場結果</h2><p>${h.output}</p></article><div class="av-learning-loop"><span>${h.feedback}</span><i></i></div></div><footer><span>HARDWARE × SOFTWARE</span><small>案例素材 · 硬體及串接流程示意</small></footer></section>`;}
export function visionLessonHTML(index){const b=visionCurriculum[index];if(!b)throw new RangeError('Unknown vision lesson');const visual=b.id==='organize'?organized():b.id==='tasks'?tasks():b.id==='train'?training():b.id==='deploy'?deployment():screen(b.id);return `<section class="av-keynote" data-av-lesson="${index}"><header><div><p class="av-kicker">AIWINOPS / LEARNING TO SEE</p><h1>${b.title}</h1></div><p>${b.subtitle}</p></header><div class="av-stage">${visual}</div><footer><span>FROM EXPERIENCE TO INTELLIGENCE</span><small>${screenTitles[b.id]?'官方產品介面':b.id==='tasks'?'AIWin Pitch · 原始案例與技術展示':b.id==='organize'?'案例素材 × 官方資料集畫面 · 整理流程示意':'流程示意'}</small></footer></section>`;}

export function createVisionLessonMotion(detail){let key=null,animations=[];const clear=()=>{animations.forEach(a=>a.cancel());animations=[];};return {reset(){clear();key=null;},render(index){if(key===index)return;clear();detail.innerHTML=visionLessonHTML(index);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const el=detail.firstElementChild;animations.push(el.animate([{opacity:0,transform:`translateX(${key!==null&&index<key?-65:65}px) scale(1.025)`},{opacity:1,transform:'none'}],{duration:900,easing:'cubic-bezier(.16,1,.3,1)'}));}key=index;}};}
